<script setup lang="ts">import { onMounted,ref } from 'vue';import { get,post } from '../api';const tab=ref('employees'),employees=ref<any[]>([]),clients=ref<any[]>([]),name=ref(''),note=ref(''),saving=ref(false);async function load(){[employees.value,clients.value]=await Promise.all([get<any[]>('/settings/employees'),get<any[]>('/settings/clients')])}onMounted(load);async function add(){if(!name.value.trim())return;saving.value=true;try{await post(`/settings/${tab.value}`,{name:name.value,note:note.value});name.value='';note.value='';await load()}finally{saving.value=false}}</script><template><div><h1 class="title">设置</h1><p class="subtitle">维护管理者使用的基础资料；员工仅为负责人数据，不具备登录权限。</p><div class="tabs"><button class="tab" :class="{active:tab==='employees'}" @click="tab='employees'">员工</button><button class="tab" :class="{active:tab==='clients'}" @click="tab='clients'">客户</button><button class="tab" disabled>业务字典</button></div><section class="form-section"><h2 class="section-title">新增{{tab==='employees'?'员工':'客户'}}</h2><form class="filters" @submit.prevent="add"><input v-model="name" class="input" :placeholder="tab==='employees'?'员工姓名':'客户名称'"/><input v-model="note" class="input" placeholder="备注（可选）"/><button class="button primary" :disabled="saving">新增</button></form></section><div class="list"><div v-for="item in tab==='employees'?employees:clients" class="list-row"><b>{{item.name}}</b><span class="subtitle">{{tab==='employees'?(item.active?'在职':'离职'):'客户主数据'}}</span><span class="subtitle">{{item.note}}</span></div></div></div></template>
